import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == 'Windows':
        command = f'start {url}'
    elif system == 'Darwin':
        command = f'open {url}'
    else:
        command = f'xdg-open {url}'
    process = subprocess.Popen(command, shell=True)
    time.sleep(0.5)
    return process.poll()

